/// Why a deconstruct lesson could not be made.
#[derive(Clone, Debug, PartialEq)]
#[non_exhaustive]
pub enum DeconstructError {
    /// A `sound/1` round could not be prepared, or a patch could not be scored.
    Round {
        /// What failed.
        message: String,
    },
    /// A render or a description failed, or a sound item did not parse.
    Sound(SoundError),
    /// The generated lesson or pack did not validate (a bug in the generator).
    Lesson(LearnError),
    /// Nothing in the preset is audible against its base: there is nothing to take apart.
    Nothing {
        /// The preset's name.
        preset: String,
    },
}

impl DeconstructError {
    /// A stable snake-case code.
    pub fn code(&self) -> &'static str {
        match self {
            DeconstructError::Round { .. } => "round_failed",
            DeconstructError::Sound(e) => e.code(),
            DeconstructError::Lesson(e) => e.code(),
            DeconstructError::Nothing { .. } => "nothing_to_deconstruct",
        }
    }

    /// What to do about it, in one line.
    pub fn hint(&self) -> String {
        match self {
            DeconstructError::Round { .. } | DeconstructError::Sound(_) => {
                "the preset could not be heard: check it renders with `enth render`".to_owned()
            }
            DeconstructError::Lesson(_) => {
                "the generated lesson is invalid: report it as a bug in lesson-gen".to_owned()
            }
            DeconstructError::Nothing { .. } => {
                "the preset sounds like its plain start: change something in it first".to_owned()
            }
        }
    }
}

impl std::fmt::Display for DeconstructError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DeconstructError::Round { message } => write!(f, "scoring failed: {message}"),
            DeconstructError::Sound(e) => write!(f, "{e}"),
            DeconstructError::Lesson(e) => write!(f, "the generated lesson does not validate: {e}"),
            DeconstructError::Nothing { preset } => {
                write!(f, "nothing in {preset} is audible against its plain start")
            }
        }
    }
}

impl std::error::Error for DeconstructError {}

/// A user's preset as a one-lesson pack: what the plugin's worker hands the session.
#[derive(Clone, Debug)]
pub struct AutoLesson {
    /// The pack, verified by [`Pack::from_files`]; its lesson's bundle is `pack.bundle(&id)`.
    pub pack: Pack,
    /// The pack's files (`pack.json` included), for the shell to keep in the user's Packs folder if it wants.
    pub files: BTreeMap<String, Vec<u8>>,
    /// What was measured and spent.
    pub report: Report,
}

/// The pack id automatic lessons go in unless the caller names another.
pub const AUTO_PACK: &str = "my-presets";

/// Make the deconstruct lesson of a user's `preset` and wrap it in a one-lesson pack (`pack_id`, default
/// [`AUTO_PACK`]), with the automatic text: the runtime job for user presets (docs/learn.md). Deterministic: the same
/// preset gives the same bytes on every platform.
///
/// # Errors
/// [`DeconstructError`] as [`generate`], and [`DeconstructError::Lesson`] if the pack does not verify.
pub fn auto_lesson(
    preset: &Patch,
    pack_id: Option<&str>,
    opts: &Options,
) -> Result<AutoLesson, DeconstructError> {
    let g = generate(preset, opts)?;
    let mut files: BTreeMap<String, Vec<u8>> = BTreeMap::new();
    files.insert(lesson_path(&opts.lesson), g.lesson.to_json().into_bytes());
    for (name, text) in &g.texts {
        files.insert(format!("lessons/{}/{name}", opts.lesson), text.clone().into_bytes());
    }
    for (path, patch) in &g.patches {
        files.insert(path.clone(), patch.to_json().into_bytes());
    }
    files.insert(
        crate::pack::CREDITS_PATH.to_owned(),
        format!(
            "# Credits\n\nGenerated by enth from the preset {} with `deconstruct` (automatic text).\n",
            build::preset_name(preset)
        )
        .into_bytes(),
    );
    let manifest = manifest_for(pack_id.unwrap_or(AUTO_PACK), &g)?;
    let sealed = manifest.seal(&files).map_err(DeconstructError::Lesson)?;
    files.insert(crate::pack::MANIFEST_PATH.to_owned(), sealed.to_json().into_bytes());
    let pack = Pack::from_files(&files).map_err(DeconstructError::Lesson)?;
    Ok(AutoLesson {
        pack,
        files,
        report: g.report,
    })
}

/// The manifest of a one-lesson pack holding `g`, with `requires` exactly what the lesson uses.
pub fn manifest_for(pack_id: &str, g: &Generated) -> Result<Manifest, DeconstructError> {
    let bad = |m: String| DeconstructError::Lesson(crate::error::bad_field(crate::error::Doc::Pack, "id", m));
    let id = PackId::new(pack_id).map_err(bad)?;
    let rounds = g.lesson.steps.iter().any(|s| matches!(s.kind, StepKind::Recreate { .. }));
    let mut covers: Vec<KindKey> = Vec::new();
    for step in &g.plan.steps {
        for i in &step.elements {
            for p in &g.plan.elements[*i].parts {
                let module = match p {
                    Part::Param(a) => a.module_id().cloned(),
                    Part::Enable(m) => Some(m.clone()),
                    Part::Route(r) => r.dst.module_id().cloned(),
                };
                if let Some((_, m)) = module.and_then(|m| g.plan.preset.find(&m).map(|(pos, m)| (pos, m.kind)))
                    && !covers.contains(&KindKey(m))
                {
                    covers.push(KindKey(m));
                }
            }
        }
    }
    covers.sort();
    Ok(Manifest {
        id,
        version: "1.0.0".parse::<PackVersion>().map_err(bad)?,
        title: "Your presets, taken apart".to_owned(),
        authors: vec!["enth (generated)".to_owned()],
        license: License {
            text: "CC-BY-4.0".to_owned(),
            patches: "CC0-1.0".to_owned(),
        },
        requires: Requires {
            lesson: crate::lesson::LESSON_VERSION,
            challenge: rounds.then_some(enth_challenge::model::CHALLENGE_VERSION),
            patch: enth_patch::file::SCHEMA,
            generator: None,
            scorers: if rounds { enth_challenge::model::RECREATE_SCORERS.to_vec() } else { Vec::new() },
        },
        engine: String::new(),
        covers,
        lessons: vec![g.lesson.id.clone()],
        tracks: Vec::new(),
        files: Vec::new(),
    })
}
